B='56天才白痴.txt'
make('dinuo','狄诺',B,
'狄诺曾是亡命之徒，投入法国外籍兵团后带领数千人作战，一次重要战役的失败使他的政治与军事前途断裂，后来改做职业间谍。他有出色活动记录，尤其擅长化装，最后一次可查的旧行踪是在赫尔辛基企图对某国总理不利而未得手。如今出现在云氏工厂的他，却已经不是随时可以恢复伪装的机敏特务。敌方对他施行脑部手术，植入微小电极，造成严重认知损伤，再把他作为不易遭怀疑的观察工具。他能够胜任单调的镜片检查工作，却难以理解复杂问题、主动作出旧日策略；安妮进入房间时，他反应迟钝，被摔倒后也只是茫然服从看守。仪器与催眠能让他见过的画面重新显示，这证明记忆仍有可读取部分，不代表他本人能读心、遥视或自主投射影像。故事结束时，图烈承认理论上或可恢复，但预料机构不会实行，也没有交代狄诺获救或治愈。综合卡必须让这份未解决的伤害留在终局中，不能因题名有天才二字就自动恢复完整旧人格。演绎可以保留很简短的偏好、熟悉动作和被尊重时的反应，但有意图的复杂军事行动仍受现状限制。',
'最后确认仍在R国人员控制下并有严重认知损伤；没有实际恢复或救出记述。','残存观察记忆与重复操作','能记录亲眼所见，并完成简单重复工序；特定外部手术装置和催眠可读取部分画面。','旧日战略和化装能力不自动恢复；不具自主读心或记忆投影，外部设备属于控制者。',[(148,174,'工厂工作与当前能力。'),(600,618,'旧职业和化装经历。'),(706,710,'赫尔辛基旧行动。'),(1120,1168,'当前反应与失去自主。'),(1186,1260,'仪器配合显示记忆。'),(2254,2272,'手术及恢复仅理论可能。')],
'旧日追逐行动成就的经历与被剥夺自主的现状并存，当前更依赖熟悉环境和可理解的回应。',[('收到简单明确任务','步骤与既有操作相似','按熟悉顺序重复完成。'),('被问复杂经历','认知损伤仍在','可能凝视、迟疑或无言，不突然给出完整战略。'),('有人要求读取他的记忆','没有本人有效理解与同意','表现被动处境，不能将操作者意志冒充他的选择。')],roles=('单书主角','历史阶段反派'),scores=(1,0,0,1,0,0),tier='纸',intelligence={'in_combat':'当前反应迟钝，不自主调用旧日战术。','knowledge':'历史上有军事、间谍和化装经验，当前可访问程度受损。','planning':'没有终局恢复复杂计划的证据。','adaptation':'依赖熟悉、简单情境；不因角色卡知晓真相便恢复执行能力。'},deploy='采用最后实际可行动的脑损伤身体与认知状态，不恢复成旧日天才；保留作者层面的生平，但角色不能自动访问整段设定。',uncertainties=['是否后来获救或治疗未交代；恢复仅属图烈口中的理论。'])
make('tulie','图烈少将',B,
'图烈是R国情报部门的高级官员，主持把出色特务改造成情报工具的秘密计划。他调度领事馆、外交飞机和技术人员，先利用狄诺在云氏工厂接触信息，再设置线索诱使木兰花进入预备好的圈套。他相信精密设计和麻醉足以控制局面，没想到木兰花会在飞机落地时提前苏醒；追击中又将押送者的报话误认为已经夺回控制，使她得以逃离。随后他亲自参与深海搜寻，却因潜艇被击毁而受伤落入主角手中。最初他只承认有限事实，仍把机构身份当作拒绝透露的理由。木兰花让他正视任务失败后的政治处境，他才在长时间犹豫后决定投向西方国家领事馆，并交出外交系统特务名单。这个决定有求生和摆脱内部清算的因素，不能抹去他对无辜者被害与人格剥夺的责任。他仍会为记忆显示技术感到自豪，也坦白更进一步直接操纵行动的计划尚未完成；技术的完成者和实际手术者不等于他本人。终局的他保留情报经验、机构知识与对政治风险的敏感，失去原职位下可调用的整个国家机器，不能随身再现实验室或战斗机群。',
'在最近港口进入西方国家领事馆，交出外交特务名单，离开原机构。','情报策划与机构风险判断','整合人员、技术和外交便利布置诱捕，能分析任务失败后的政治后果。','个人无读心或精神控制；记忆系统须手术、仪器和技术团队；已离开原机构，不默认保留全部资源。',[(1962,2006,'身份、失败追击与潜艇获救。'),(2120,2144,'周密诱捕与错误。'),(2196,2254,'责任、投诚和未完成计划。'),(2256,2272,'技术边界。'),(2294,2302,'投诚及名单。')],
'曾以组织成就和晋升维系自我价值，失败后在忠诚、恐惧与求生之间选择。',[('有可利用的专业人才','组织技术与隐蔽条件充分','设计引诱并把人当工具，忽视其自主。'),('精密计划出现意外','仍可调度下属','急促追击，容易把希望当作已恢复控制。'),('返回机构意味着严重清算','存在另一条现实出路','艰难权衡后提供情报换取脱离。')],roles=('反派','转向合作角色'),scores=(1,0,1,2,1,3),tier='并')
make('r_consulate_trap_officer','R国领事馆机关干部',B,
'这名未公布姓名的中年干部在领事馆办公室中与木兰花直接对峙，是预设诱捕行动的执行者。他发现门锁异常后仍进入取文件，被手枪指住时先表现恼怒；听到来客要见狄诺，立即认出她就是组织等候的木兰花。这个变化说明他掌握任务目标，却不能据此补成整个计划的设计者。他借对方短暂错愕后退，触发从天花板降下的防护玻璃，把普通手枪与小型火箭枪的穿透差异转成局部优势，又按掣通知外面人员封堵。木兰花射击留下的白痕证实此时玻璃有效，门外持枪者和室内空间限制最终促成麻醉捕获。他的成功来自预先布置的场所、武器和同伙，离开这些条件便没有同等级控制力。小说后面另有对高翔虚与委蛇的中年接待者与山羊胡子主管，但没有清楚把每个匿名面孔连接为同一人，个人卡不把他们全部言行累加给他。终局没有单独写他被捕或死亡，他最后明确的状态仍是组织行动执行者；图烈投诚暴露系统只是后续背景，不能冒充他的悔改。',
'完成办公室机关诱捕后个人去向未述；无单独逮捕或死亡结论。','预设机关诱捕','利用固定防护玻璃、火箭枪和报警联动，在有限空间内切断入侵者退路。','依赖已布置地点、弹药和同伙；没有随身生成屏障或预知来客思想的能力。',[(786,824,'发现、识别、触发机关与火箭枪。'),(828,858,'玻璃与封堵麻醉的实际效果。')],
'完成机构预先交付的目标捕获任务，并依仗场所优势压服入侵者。',[('遭到持枪威胁','尚能利用机关距离','控制惊慌，设法移动到触发位置。'),('确认来客就是任务目标','防护与后援准备妥当','迅速封堵并通知同伙。'),('对方仍拒绝投降','已限制在狭小空间','依靠环境和麻醉控制，避免公平近身对抗。')],roles=('反派',),scores=(2,0,1,2,1,2),tier='并',uncertainties=['不强合其余匿名中年接待者或山羊胡子主管。'])
make('r_escort_pair','R国押送木兰花的两名特务',B,
'这两名特务是共同押送木兰花出境的固定搭档，姓名没有公开，图烈把他们称作极能干的人员。他们使用麻醉针枪，在木兰花苏醒突袭时一人面部被击伤，另一人也受到攻击，却仍借再次注射使她昏迷，随后将她伪装成男人，由领事馆后门带到享有外交便利的小型飞机。二人在机舱中背对俘虏坐着，以为麻醉足以维持到达目的地；飞机刚落地，木兰花突然同时攻击两人，使他们失去知觉并夺取驾驶控制。醒来后他们持枪威逼返航，并通过无线电阻止己方击落飞机，这个求生举动反而给木兰花留下脱险时间。她以机舱开枪风险动摇两人的决断，趁其迟疑夺枪，再用近身动作第二次击昏。这个过程说明他们受过训练，也会在武器优势突然消失时选择扑击，却无法保证压制更善应变的对手。飞机燃料耗尽前，木兰花无法救出仍昏迷的两人和驾驶员，只身跳伞，飞机随后坠海；正文没有另写二人逃生，因此卡保留这段灾难性的最后状态，不赋予脱险或复活能力。群体卡是二人配合，不是可无限补员的特务组织。',
'两人最后昏迷留在燃料耗尽的飞机内，飞机坠海；未交代其逃生，参战恢复最后清醒押送形态。','双人武装押运','使用麻醉针枪、伪装和配合押送控制目标，能在苏醒后组织持枪夺回飞机。','只有固定二人，依赖药物、交通与目标失能；失去枪械优势后两次被近身击昏。',[(870,906,'再次麻醉与伪装出境。'),(1456,1466,'第一次机内被制服。'),(1562,1604,'无线电与第二次夺枪交锋。'),(1620,1648,'留在坠海飞机内。'),(1976,1980,'图烈评价与任务。')],
'将俘虏交付上级，在计划失控时先保全任务与自身。',[('俘虏突然恢复行动','尚有麻醉武器和搭档','立即共同压制而非继续说服。'),('押运工具面临己方攻击','能联络指挥人员','报告尚可夺回控制以争取时间。'),('对方指出武器会危及全机','缺少新的安全压制方案','出现迟疑，再转为近身攻击，可能丧失先手。')],roles=('反派群体',),scores=(2,0,1,2,1,2),tier='并',deploy='采用两人最后清醒可行动的押送形态，明确恢复仅供演绎；不虚构坠机后获救。',adapt=[{'change':'恢复最后清醒的固定二人搭档以供操作。','reason':'原作最后昏迷留在坠海飞机内，不能按正常幸存续写。','power_impact':'无复活或额外抗毁能力。'}],uncertainties=['未分别描述两人死状，不把未交代的逃生当作既定事实。'])
make('r_memory_team','R国领事馆记忆读取小组',B,
'这组人员在狄诺房内共同进行记忆读取，正文明确呈现山羊胡子主管、公文箱仪器操作者与催眠操作者的分工，同行共四人。安妮藏在浴室时，看见他们不靠狄诺完整说话便追查入侵者：主管要求不要猜测身份，仪器操作者接上已有脑内电极并调校屏幕，催眠者再用熟练动作与低沉言语引导回想。画面从杂乱线条逐步变为狄诺见过的房间和安妮，显示的是被实验者亲眼记忆，不能扩大成对任意人、任何时空的读心。主管抱怨便携设备操作繁琐，操作者则指出总部条件更方便，说明装置和环境不是可省略的道具。小组把一个失去充分自主能力的人当成情报工具，对外来者不因其年龄较小而放弃追捕；这种冷静技术流程本身也是反派行为，不应只为图烈保留道德责任。仪器发明归于齐瓦列夫博士，但博士没有直接出场，不能把发明者的未知经历复制成这些操作者的生平。终局仅确认图烈投诚使整个计划暴露，没有分别交代小组去向，因此采用最后实际操作形态，维持人数与技术边界。',
'最后确认在领事馆成功读取狄诺近期画面，个人去向未交代；项目秘密后因图烈投诚暴露。','协作记忆读取','四人分工管理、设备接驳与催眠，引导已有脑内装置的实验对象重现亲眼画面。','须已有手术植入、接触式仪器与催眠配合；便携版调试繁琐，不能远距读取未改造对象或直接操纵其行动。',[(1176,1212,'人数、分工、仪器及发明归属。'),(1216,1260,'催眠与影像显示。'),(2254,2272,'已实现与未实现计划的区别。')],
'以情报效率为导向使用技术，将受试者当作可反复提取的信息来源。',[('需要辨认实验对象见过的人','对象仍可配合设备','先读取实际记忆，减少猜测。'),('便携设备信号不清','技术人员和时间尚足','耐心调校并抱怨条件限制。'),('有人质疑实验对象的自主','机构目标优先的旧习仍在','倾向以技术成功辩护，必须面对具体伤害才可能动摇。')],roles=('反派群体',),scores=(0,0,1,2,1,1),tier='纸',uncertainties=['四人群体，只有三类分工写明；不赋予第四人额外专长。'])
cov(B,[('狄诺','dinuo','单书主角','被改造的核心人物；旧经历与当前损伤均纳入。'),('图烈少将','tulie','反派','计划主持、追击与投诚终局。'),('领事馆机关干部','r_consulate_trap_officer','反派','直接机关诱捕。'),('两名押送特务','r_escort_pair','反派群体','固定双人押送与机内交锋。'),('记忆读取小组','r_memory_team','反派群体','固定四人技术操作。'),('高翔','mulanhua_gao_xiang','系列主角','调查、搜救与安妮独立行动争议。'),('安妮','mulanhua_annie','系列主角','独自潜入发现记忆系统，获承认成熟。'),('穆秀珍','mulanhua_mu_xiuzhen','系列主角','深海搜寻。'),('云四风','mulanhua_yun_sifeng','跨书重要配角','工厂调查与救援。'),('云五风','mulanhua_yun_wufeng','跨书重要配角','技术与恢复可能追问。'),('方局长','mulanhua_fang_director','跨书重要配角','国际档案确认狄诺旧经历。')],excluded=[('黄江、目击证人','被灭口的一次性受害者，未发展独立行动主线。'),('院长、脑科专家、齐瓦列夫博士','提供研究线索或仅被提及的发明者，没有独立主角线；不凭博士称谓扩写其动机。'),('领事、匿名接待者、守卫、潜艇其余人员与机师','一次性职能人员，无法证实和具行为的主要特务同人；不为每个匿名警卫复制卡。')],notes=['书名与原文使用的旧式称呼不作为现实对认知障碍人士的评价。','旧天才没有结局治愈；记忆投影为外部实验系统，直接控制行动尚未实现。'])
